def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        value = value or ""
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in {"0", "1"}

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Unsupported updated date: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))

        email_ok = valid_email(email)
        phone_ok = valid_phone(phone)

        # Rows without either usable contact identifier cannot be matched or sent.
        if not email_ok and not phone_ok:
            continue

        normalized_rows.append({
            "input_index": input_index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "zip": normalize_zip(row.get("zip", "")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": (row.get("source", "") or "").strip().lower(),
            "tags_raw": row.get("tags", "") or "",
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "updated_dt": parse_updated(row["updated"]),
        })

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        last_name_key = row["last_name"].casefold()
        if row["phone"] and last_name_key:
            key = (row["phone"], last_name_key)
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index in range(count):
        groups.setdefault(find(index), []).append(index)

    def choose_field(member_indexes, field):
        candidates = [
            normalized_rows[index]
            for index in member_indexes
            if normalized_rows[index][field] != ""
        ]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return chosen[field]

    output = []

    ordered_groups = sorted(
        groups.values(),
        key=lambda members: min(
            normalized_rows[index]["input_index"] for index in members
        ),
    )

    for members in ordered_groups:
        tags = set()
        opted_out = False
        latest_updated = max(
            normalized_rows[index]["updated_dt"] for index in members
        )

        for index in members:
            row = normalized_rows[index]
            opted_out = opted_out or row["opted_out"]

            for tag in re.split(r"[;,]", row["tags_raw"]):
                tag = tag.strip().lower()
                if tag:
                    tags.add(tag)

        output.append({
            "first_name": choose_field(members, "first_name"),
            "last_name": choose_field(members, "last_name"),
            "zip": choose_field(members, "zip"),
            "email": choose_field(members, "email"),
            "phone": choose_field(members, "phone"),
            "source": choose_field(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if opted_out else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
